-- Additive Takt 3 migration; no existing rows are removed.
CREATE TABLE IF NOT EXISTS specialist_options(company_id TEXT PRIMARY KEY REFERENCES companies(id),data TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS specialist_handles(handle TEXT PRIMARY KEY COLLATE NOCASE,company_id TEXT NOT NULL REFERENCES companies(id),created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS handles_company ON specialist_handles(company_id);
CREATE TRIGGER IF NOT EXISTS booking_buffer_0 BEFORE INSERT ON bookings WHEN NEW.status IN ('pending','confirmed') AND EXISTS(SELECT 1 FROM bookings b WHERE b.company_id=NEW.company_id AND b.id<>NEW.id AND b.status IN ('pending','confirmed') AND b.starts_at<NEW.ends_at+COALESCE((SELECT json_extract(data,'$.buffer')*60 FROM specialist_options WHERE company_id=NEW.company_id),0) AND b.ends_at+COALESCE((SELECT json_extract(data,'$.buffer')*60 FROM specialist_options WHERE company_id=NEW.company_id),0)>NEW.starts_at) BEGIN SELECT RAISE(ABORT,'SLOT_TAKEN'); END;
CREATE TRIGGER IF NOT EXISTS booking_buffer_1 BEFORE UPDATE OF starts_at,ends_at,status ON bookings WHEN NEW.status IN ('pending','confirmed') AND EXISTS(SELECT 1 FROM bookings b WHERE b.company_id=NEW.company_id AND b.id<>NEW.id AND b.status IN ('pending','confirmed') AND b.starts_at<NEW.ends_at+COALESCE((SELECT json_extract(data,'$.buffer')*60 FROM specialist_options WHERE company_id=NEW.company_id),0) AND b.ends_at+COALESCE((SELECT json_extract(data,'$.buffer')*60 FROM specialist_options WHERE company_id=NEW.company_id),0)>NEW.starts_at) BEGIN SELECT RAISE(ABORT,'SLOT_TAKEN'); END;
